// Scene-owned solar inventory. The grouping matches the existing collector network.
export function banks80(T,slots,contacts){
 const xs=[...new Set(slots.map(p=>p.x))].sort((a,b)=>a-b);
 return [0,1,2].map(index=>{
  const members=slots.map((slot,i)=>({slot,contact:contacts[i]})).filter(({slot})=>Math.min(2,Math.floor(xs.indexOf(slot.x)*3/xs.length))===index);
  const bank=new T.Group(); bank.name=`Connected_PV_Collector_${index+1}`;
  bank.userData={moduleCount:members.length,moduleWatts:620,members,collectorX:Math.min(...members.map(p=>p.slot.x))-3.25,collectorZ:Math.max(...members.map(p=>p.contact?.z??p.slot.z))};
  return bank;
 });
}
// Three DC branches tap the already cabled field collectors. Rebuild only after edits.
export function wireBess80(T,root,battery,banks){
 if(!root||!battery||banks.length!==3)return;
 battery.updateWorldMatrix(true,false);root.updateWorldMatrix(true,false);
 let old149=root.userData.bessState149,changed149=!old149;if(!old149)old149=root.userData.bessState149=new Float64Array(41);for(let i=0;i<32;i++){const value=i<16?battery.matrixWorld.elements[i]:root.matrixWorld.elements[i-16];if(old149[i]!==value)changed149=true;old149[i]=value;}for(let i=0;i<3;i++){const d=banks[i].userData;for(let j=0;j<3;j++){const value=j===0?d.collectorX:j===1?d.collectorZ:d.moduleCount,k=32+i*3+j;if(old149[k]!==value)changed149=true;old149[k]=value;}}if(!changed149)return;
 const ends=banks.map((b,i)=>battery.localToWorld(new T.Vector3(-2.34,.36,-.58+i*.58)));
 const key=ends.flatMap(p=>p.toArray()).map(v=>v.toFixed(3)).join(':');
 if(root.userData.bessCableKey===key)return;
 root.userData.bessCableKey=key;
 let cables=root.getObjectByName('BESS_DC_Collector_Cables');
 if(!cables){cables=new T.Group();cables.name='BESS_DC_Collector_Cables';cables.userData.editLocked=true;root.add(cables);}
 while(cables.children.length){const old=cables.children[0];old.geometry.dispose();old.material.dispose();cables.remove(old);}
 banks.forEach((bank,i)=>{
  const {collectorX:x,collectorZ:z}=bank.userData,end=ends[i];
  // Ground-level raceway passes in front of the parked excavator, outside its footprint.
  const y=.27+i*.025,front=-144.1+i*.16,lane=95.1+i*.2;
  const points=[[x,.53,z],[x,y,z],[x,y,front],[lane,y,front],[lane,y,end.z],[end.x,end.y,end.z]].map(p=>root.worldToLocal(new T.Vector3(...p)));
  const path=new T.CurvePath();for(let j=1;j<points.length;j++)path.add(new T.LineCurve3(points[j-1],points[j]));
  const cable=new T.Mesh(new T.TubeGeometry(path,96,.034,6,false),new T.MeshStandardMaterial({color:[0x2d4850,0x304149,0x3a5053][i],roughness:.73,metalness:.1}));
  cable.name=`BESS_Bank_${i+1}_DC_Cable`;cable.userData={moduleCount:bank.userData.moduleCount,moduleWatts:620,connected:true};cables.add(cable);
 });
 root.userData.solarArray={moduleCount:banks.reduce((s,b)=>s+b.userData.moduleCount,0),moduleWatts:620,bankCounts:banks.map(b=>b.userData.moduleCount),peakKw:banks.reduce((s,b)=>s+b.userData.moduleCount*.62,0)};
}

